select avg(p.id) over w as mean, min(p.title) over w as first_title, bool_and(p.id > 0) over w as all_positive, bit_or(p.id) over w as bits, string_agg(p.title, ', ') over w as titles, array_agg(p.title) over w as title_list, array_agg(p.note) over w as note_list, jsonb_agg(p.note) over w as notes, json_object_agg(p.title, p.note) over w as by_title from posts p window w as (partition by p.user_id)
